<?php
require_once __DIR__.'/../../backend/extend/yuzhou/bootstrap.php';
use yuzhou\Database;
use yuzhou\Api;
use yuzhou\ApiError;
use yuzhou\Catalog;
use yuzhou\Rbac;
$checks=0;
function crmCheck($condition,$label) { global $checks; if (!$condition) throw new RuntimeException($label); $checks++; }
function crmReject($callback,$status,$label) { try { $callback(); } catch(ApiError $e) { crmCheck($e->status===$status,$label); return; } throw new RuntimeException($label); }
putenv('APP_ENV=test'); $db=new Database(new PDO('sqlite::memory:'));
$db->pdo->exec(file_get_contents(__DIR__.'/../../database/sqlite.sql'));
$db->pdo->exec(file_get_contents(__DIR__.'/../../database/communication-sqlite.sql'));
foreach(glob(__DIR__.'/../../database/migrations/*-sqlite.sql') as $path) $db->pdo->exec(file_get_contents($path));
$now=time();$u=[];
foreach(['agency','agency','merchant'] as $kind) $db->insert('organizations',['name'=>'Synthetic '.$kind,'kind'=>$kind,'status'=>'approved','payload'=>'{}','created_at'=>$now]);
foreach(['platform'=>null,'agency'=>1,'broker'=>1,'otheragency'=>2,'otherbroker'=>2,'merchant'=>3,'consumer'=>null,'limited'=>null] as $name=>$org) {
    $role=strpos($name,'other')===0?substr($name,5):($name==='limited'?'platform':$name);
    $id=$db->insert('users',['username'=>'crm_'.$name,'password_hash'=>'unused','nickname'=>$name,'role'=>$role,'org_id'=>$org,'created_at'=>$now,'updated_at'=>$now]);
    $u[$name]=$db->one('SELECT * FROM users WHERE id=?',[$id]);
    $db->insert('tokens',['user_id'=>$id,'token_hash'=>hash('sha256','crm-token-'.$name),'expires_at'=>$now+3600,'created_at'=>$now]);
}
$customer=$db->insert('customers',['user_id'=>$u['consumer']['id'],'broker_id'=>$u['broker']['id'],'org_id'=>1,'name'=>'Synthetic customer','notes'=>'','stage'=>'new','created_at'=>$now,'updated_at'=>$now]);
$api=new Api($db);
$call=function($method,$path,$body=[],$query=[],$role='agency')use($api){return $api->dispatch($method,$path,$body,$query,'crm-token-'.$role);};
$tag=$call('POST','customer-tags',['name'=>'Ready to buy','color'=>'#22AAFF']);
crmCheck((int)$tag['org_id']===1&&$tag['color']==='#22aaff','Tags retain their agency and normalized color');
crmReject(function()use($call){$call('POST','customer-tags',['name'=>'Ready to buy']);},409,'Tag names unique within company');
$other=$call('POST','customer-tags',['name'=>'Ready to buy'],[],'otheragency');
crmCheck((int)$other['org_id']===2,'Same name may be used by another company');
crmCheck($call('GET','customer-tags',[],[],'broker')['total']===1,'Broker only reads own company tags');
crmCheck($call('GET','customer-tags',[],['org_id'=>1],'platform')['total']===1,'Platform can filter a company');
crmReject(function()use($call){$call('GET','customer-tags',[],['org_id'=>2],'broker');},403,'Broker cannot query other company');
crmReject(function()use($call){$call('POST','customer-tags',['name'=>'Unauthorized'],[],'broker');},403,'Broker cannot create company labels');
crmReject(function()use($call){$call('GET','customer-tags',[],[],'merchant');},403,'Merchant cannot access company CRM');
$assigned=$call('PUT','customers/'.$customer.'/tags',['tag_ids'=>[$tag['id'],$tag['id']]],[],'broker');
crmCheck(count($assigned['tags'])===1&&$assigned['tags'][0]['id']===(int)$tag['id'],'Tag replacement is structured and deduplicated');
crmCheck(count($call('GET','customers',[],['tag_id'=>$tag['id']],'broker')['items'][0]['tags'])===1,'Customer listing and tag filter use relation');
crmReject(function()use($call,$customer,$other){$call('PUT','customers/'.$customer.'/tags',['tag_ids'=>[$other['id']]],[],'broker');},403,'Cross-company tagging rejected');
crmCheck((int)$db->scalar('SELECT COUNT(*) FROM customer_tag_links WHERE customer_id=?',[$customer])===1,'Failed replacement preserves old tags');
crmReject(function()use($call,$customer,$tag){$call('PUT','customers/'.$customer.'/tags',['tag_ids'=>[$tag['id']]],[],'otherbroker');},404,'Other broker cannot label customer');
$call('PATCH','customer-tags/'.$tag['id'],['status'=>'inactive']);
crmReject(function()use($call,$customer,$tag){$call('PUT','customers/'.$customer.'/tags',['tag_ids'=>[$tag['id']]],[],'broker');},403,'Inactive tag cannot be newly assigned');
crmCheck($call('PUT','customers/'.$customer.'/tags',['tag_ids'=>[]],[],'broker')['tags']===[],'Tags can be cleared');
crmReject(function()use($call,$tag){$call('PATCH','customer-tags/'.$tag['id'],['org_id'=>2],[],'platform');},403,'Tag company immutable');
crmReject(function()use($call){$call('POST','customer-tags',['name'=>'Invalid','color'=>'red']);},422,'Hex color validated');
$month=date('Y-m');$empty=$call('GET','agency-targets',[],['month'=>$month],'broker');
crmCheck($empty['configured']===false&&$empty['target_amount_cents']===0,'Missing monthly target is explicit');
$target=$call('PUT','agency-targets/'.$month,['target_amount_cents'=>15000]);
crmCheck($target['configured']===true&&$target['target_amount_cents']===15000,'Company can configure monthly target');
crmReject(function()use($call,$month){$call('PUT','agency-targets/'.$month,['target_amount_cents'=>1],[],'broker');},403,'Broker cannot change company target');
crmReject(function()use($call,$month){$call('PUT','agency-targets/'.$month,['org_id'=>2,'target_amount_cents'=>1]);},403,'Company cannot change another target');
crmReject(function()use($call){$call('GET','agency-targets',[],['month'=>'2026-13']);},422,'Invalid target month rejected');
crmReject(function()use($call){$call('PUT','agency-targets/2026-10',['org_id'=>3,'target_amount_cents'=>1],[],'platform');},404,'Merchant organization cannot masquerade as company target');
$cat=new Catalog($db);$service=$cat->save('maintenance',['title'=>'Synthetic company service','price_cents'=>10000,'payload'=>[]],$u['platform']);
$order=$db->insert('orders',['order_no'=>'CRM-TARGET','type'=>'maintenance','customer_id'=>$u['consumer']['id'],'creator_id'=>$u['broker']['id'],'broker_id'=>$u['broker']['id'],'org_id'=>1,'resource_id'=>$service['id'],'status'=>'paid','amount_cents'=>10000,'original_amount_cents'=>10000,'paid_cents'=>10000,'items'=>'[]','notes'=>'','created_at'=>strtotime('2025-01-01'),'updated_at'=>$now]);
$db->insert('payments',['order_id'=>$order,'amount_cents'=>10000,'channel'=>'test','status'=>'succeeded','idempotency_key'=>'crm-pay-current','created_at'=>$now]);
$db->insert('payments',['order_id'=>$order,'amount_cents'=>500,'channel'=>'test','status'=>'succeeded','idempotency_key'=>'crm-pay-old','created_at'=>strtotime('-2 months')]);
$db->insert('refunds',['order_id'=>$order,'amount_cents'=>2000,'reason'=>'Synthetic refund','channel'=>'test','status'=>'succeeded','idempotency_key'=>'crm-refund-current','created_at'=>$now]);
$metrics=$call('GET','agency-targets',[],['month'=>$month],'broker');
crmCheck($metrics['actual_paid_cents']===10000&&$metrics['actual_refund_cents']===2000&&$metrics['actual_net_paid_cents']===8000,'Performance uses successful receipt/refund month, not order creation');
crmCheck($call('GET','agency-targets',[],['month'=>$month],'otheragency')['actual_paid_cents']===0,'Performance is isolated by company');
$role=(new Rbac($db))->dispatch('POST','admin/roles',['name'=>'Finance only','base_role'=>'platform','permissions'=>['finance']],[],$u['platform']);
(new Rbac($db))->dispatch('PUT','admin/users/'.$u['limited']['id'].'/roles',['role_ids'=>[$role['id']]],[],$u['platform']);
crmReject(function()use($call){$call('GET','customer-tags',[],[],'limited');},403,'Sub-role permission guards CRM tags');
crmReject(function()use($call,$month){$call('PUT','agency-targets/'.$month,['org_id'=>1,'target_amount_cents'=>1],[],'limited');},403,'Sub-role permission guards target edits');
$type=$cat->save('boat_types',['title'=>'Synthetic type','payload'=>[]],$u['platform']);
$boat=$cat->save('boats',['title'=>'Synthetic actual boat','payload'=>['boat_type_id'=>$type['id'],'serial_number'=>'CRM-MAP-BOAT']],$u['platform']);
crmCheck($boat['payload']['latitude']===null&&$boat['payload']['longitude']===null,'Missing coordinates stay empty');
$boat=$cat->save('boats',['version'=>$boat['version'],'payload'=>$boat['payload']+[]],$u['platform'],$boat['id']);
$payload=$boat['payload'];$payload['latitude']=31.2345678;$payload['longitude']=121.456789;
$boat=$cat->save('boats',['version'=>$boat['version'],'payload'=>$payload],$u['platform'],$boat['id']);
crmCheck($cat->listing('boats',[])['items'][0]['payload']['latitude']===31.2345678,'Real supplied coordinates appear in public boat list');
crmReject(function()use($cat,$boat,$u){$payload=$boat['payload'];$payload['latitude']=91;$cat->save('boats',['version'=>$boat['version'],'payload'=>$payload],$u['platform'],$boat['id']);},422,'Out-of-bounds latitude rejected');
crmReject(function()use($cat,$boat,$u){$payload=$boat['payload'];$payload['latitude']=null;$cat->save('boats',['version'=>$boat['version'],'payload'=>$payload],$u['platform'],$boat['id']);},422,'Partial coordinate clearing rejected');
$payload=$boat['payload'];$payload['latitude']=null;$payload['longitude']=null;
$boat=$cat->save('boats',['version'=>$boat['version'],'payload'=>$payload],$u['platform'],$boat['id']);
crmCheck((int)$db->scalar('SELECT COUNT(*) FROM boat_locations WHERE boat_id=?',[$boat['id']])===0,'Clearing removes typed coordinate row');
crmCheck($api->dispatch('GET','recommendations')['based_on']==='recently_published','Recommendation route supports anonymous cold start');
echo 'CRM and map checks: '.$checks.' passed.'.PHP_EOL;
